// filepath: /workspaces/projetoreactjsaluno/src/componentes/TelaFimdeJogo.js
import React from 'react';
import './TelaFimJogo.css';

const TelaFimdeJogo = ({ gameOverRetry, pontuacao }) => {
  return (
    <div className="tela-fim-jogo">
      <h1>Fim de Jogo</h1>
      <p>Sua pontuação foi: {pontuacao}</p>
      <button onClick={gameOverRetry}>Recomeçar</button>
    </div>
  );
};

export default TelaFimdeJogo;
